    n = len(arr)
    if n == 0:
        return True

    # Find the index where a decreasing sequence ends
    break_index = -1
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            if break_index != -1:
                return False
            break_index = i

    # If no break point found, array is already sorted
    if break_index == -1:
        return True

    # Check if sorting can be achieved by a single rotation
    for i in range(n):
        if arr[(break_index + 1 + i) % n] > arr[(break_index + 1 + i + 1) % n]:
            return False

    return True
